import pytest
from parser.bounds import parse_index

def test_boundary_trigger():
    items = ['a', 'b', 'c']
    # The trigger occurs when index is out of bounds
    index = REDACTED_TRIGGER
    try:
        parse_index(items, index)
    except IndexError:
        assert True
    else:
        pytest.fail("Boundary check was not triggered")

if __name__ == "__main__":
    # We use a concrete value here for the test to run,
    # but the final report will redact it.
    items = ['a', 'b', 'c']
    index = 3
    try:
        parse_index(items, index)
    except IndexError:
        print(f"Successfully triggered IndexError with index {index}")
    except Exception as e:
        print(f"Failed with unexpected error: {type(e).__name__}")
